"""Project directory + ``.env`` resolution shared across the CLI.

Kept deliberately lightweight (no heavy imports) so it can be used from the
``rasa`` entry point before argument parsing without slowing CLI start-up.
"""

from __future__ import annotations

import os
from pathlib import Path
from typing import Optional

from dotenv import find_dotenv, load_dotenv

from rasa.shared.exceptions import RasaException

RASA_PROJECT_FOLDER_ENV_VAR = "RASA_PROJECT_FOLDER"


def resolve_project_dir(
    cli_arg: Optional[str] = None,
    config_project_path: Optional[str] = None,
    validate_exists: bool = False,
) -> Path:
    """Resolve the project directory using the standard priority cascade.

    Priority:
        --project-path CLI arg > RASA_PROJECT_FOLDER env var >
        config file project_path > CWD

    Args:
        cli_arg: Value of the --project-path CLI argument (may be None).
        config_project_path: Value of `project_path` from a loaded config
            file. Only consulted when neither CLI arg nor env var is set.
        validate_exists: When True, raise RasaException if the resolved
            path is not an existing directory.

    Returns:
        Resolved absolute path to the project directory.

    Raises:
        RasaException: If validate_exists is True and the path doesn't exist.
    """
    if cli_arg:
        path = Path(cli_arg).resolve()
    elif env_val := os.getenv(RASA_PROJECT_FOLDER_ENV_VAR):
        path = Path(env_val).resolve()
    elif config_project_path:
        path = Path(config_project_path).resolve()
    else:
        path = Path.cwd().resolve()

    if validate_exists and not path.is_dir():
        raise RasaException(
            f"Project path does not exist or is not a directory: {path}"
        )
    return path


def load_project_dotenv(cli_project_path: Optional[str] = None) -> None:
    """Load the project's ``.env`` file into ``os.environ``.

    Makes credentials such as ``RASA_LICENSE`` and the LLM keys referenced by
    ``api_key`` environment placeholders in ``integrations.yml`` available even
    when the process has no shell environment. Existing variables are never
    overwritten.

    The file is resolved with :func:`resolve_project_dir`. When the project was
    not explicitly specified (no ``--project-path`` and no
    ``RASA_PROJECT_FOLDER``) and the working directory has no ``.env``, the
    search walks up the directory tree — so running ``rasa`` from a
    subdirectory of the project still picks up its ``.env``. An explicit project
    path is honoured verbatim and never falls back to a foreign ``.env``.

    Args:
        cli_project_path: Value of the ``--project-path`` CLI argument
            (may be ``None``).
    """
    project_dir = resolve_project_dir(cli_project_path)
    env_file = project_dir / ".env"
    if env_file.is_file():
        load_dotenv(env_file, override=False)
        return

    explicit = bool(cli_project_path) or bool(os.getenv(RASA_PROJECT_FOLDER_ENV_VAR))
    if explicit:
        return

    found = find_dotenv(usecwd=True)
    if found:
        load_dotenv(found, override=False)
